/*@@SAFELAB_LIB@@*/

// ---- Shared helpers (same block in every SafeLab workflow) ----
const rowsOf = (node) => $(node).all().map((i) => i.json).filter((r) => r && Object.keys(r).length);
const now = $now.setZone('Asia/Ho_Chi_Minh');
const today = now.toFormat('yyyy-MM-dd');
const nowIso = now.toFormat("yyyy-MM-dd'T'HH:mm:ssZZ"); // e.g. 2026-10-11T21:30:00+07:00
const year = now.year;
const esc = SafeLab.escapeHtml;
const text = (v) => (v === null || v === undefined ? '' : String(v).trim());
const lower = (v) => text(v).toLowerCase();
// Google Sheets treats text starting with = + - @ as a formula: prefix ' so it is stored as plain text.
const sheetRow = (row) => Object.fromEntries(Object.entries(row).map(([k, v]) =>
  [k, typeof v === 'string' && /^[=+\-@]/.test(v) ? "'" + v : v]));
const audit = (actor, action, entity, entityId, details) =>
  sheetRow({ ts: nowIso, actor: actor || 'system', action, entity, entity_id: entityId, details: text(details).slice(0, 1000) });
const link = (url, label) =>
  (text(url) ? `<a href="${esc(url)}">${esc(label)}</a>` : `${esc(label)} (link not configured in CONFIG)`);
const mail = (to, subject, body) => ({
  to: [...new Set([].concat(to).map(lower).filter(Boolean))].join(', '),
  subject: text(subject).replace(/\s+/g, ' '),
  html: `<div style="font-family:Arial,sans-serif;font-size:14px;line-height:1.5;color:#111">${body}` +
    '<p style="color:#6b7280;font-size:12px;margin-top:24px">Automated message from SafeLab (lab-safety approval system).</p></div>',
});
const cfg = SafeLab.configMap(rowsOf('Read CONFIG'));

// ---- 01 Person onboard: F01 row -> upsert PEOPLE, welcome email ----
const existing = {};
rowsOf('Read PEOPLE').forEach((p) => { if (lower(p.email)) existing[lower(p.email)] = p; });
const requiredForAll = rowsOf('Read TRAINING_TYPES').filter((t) =>
  SafeLab.parseList(t.required_for).some((x) => x.toUpperCase() === 'ALL'));

const people = {};
const auditRows = [];
const emails = [];

for (const r of rowsOf('F01 row added')) {
  const email = lower(r['Email Address']);
  if (!email) continue;
  const before = existing[email];
  const person = {
    email,
    full_name: text(r['Full name']),
    role: text(r['Role']),
    project: text(r['Project']),
    supervisor_email: lower(r['Supervisor email']),
    vn_osh_group: text(r['Vietnam OSH training group']),
    status: 'ACTIVE',
    registered_at: (before && text(before.registered_at)) || nowIso,
    updated_at: nowIso,
  };
  people[email] = sheetRow(person); // several submissions in one poll: the last one wins

  auditRows.push(audit(email, before ? 'PERSON_UPDATED' : 'PERSON_REGISTERED', 'PEOPLE', email,
    `${person.role}; project ${person.project || '-'}; OSH ${person.vn_osh_group || '-'}`));

  const trainings = requiredForAll.map((t) => {
    const months = Number(t.validity_months) || 0;
    const validity = months > 0 ? `valid ${months} months` : 'does not expire';
    const material = text(t.link) ? ` – ${link(t.link, 'training material')}` : '';
    return `<li><b>${esc(t.training_code)}</b> – ${esc(t.name)} (${validity})${material}</li>`;
  }).join('');
  const oshNote = !person.vn_osh_group || person.vn_osh_group.toLowerCase() === 'not yet classified'
    ? '<p><b>Note:</b> your Vietnam OSH training group is not classified yet – please confirm it with your supervisor.</p>'
    : '';
  emails.push(mail(email, `[SafeLab] ${before ? 'Registration updated' : 'Welcome to SafeLab'} – ${person.full_name || email}`,
    `<h2>${before ? 'Your SafeLab registration was updated' : 'Welcome to SafeLab'}, ${esc(person.full_name || email)}</h2>` +
    `<p>Role: <b>${esc(person.role)}</b> · Project: <b>${esc(person.project || '-')}</b> · ` +
    `Vietnam OSH group: <b>${esc(person.vn_osh_group || '-')}</b></p>` + oshNote +
    `<p><b>Training required for everyone:</b></p><ul>${trainings || '<li>(none configured)</li>'}</ul>` +
    '<p><b>Next steps</b></p><ol>' +
    `<li>After completing each training, record it with the ${link(cfg.FORM_F02_URL, 'Training Record form (F02)')}.</li>` +
    `<li>Read and acknowledge the SOPs for your work with the ${link(cfg.FORM_F03_URL, 'SOP Acknowledgement form (F03)')}.</li>` +
    '<li>Only then submit an Experimental Safety Approval (F04) – it is checked automatically against your training and SOP records.</li>' +
    '</ol>'));
}

return [{ json: { people: Object.values(people), audit: auditRows, emails: emails.filter((e) => e.to) } }];
